"""MCP tools for browsing and exchanging supplier negotiation emails in the Arena."""

from __future__ import annotations

import logging
import math
import os
import threading
from dataclasses import dataclass, field
from typing import Any, Literal

from dotenv import load_dotenv
from mcp.server import MCPServer

from .agent import TaktikaAgent
from .client import ArenaClient
from .cost_model import complete_offer, must_haves_ok
from .document_reader import supplier_standard_terms
from .play import RemoteTable, load_attachments, live_threads, standing

log = logging.getLogger("taktika.mcp")
server = MCPServer("taktika-arena-email")


@dataclass
class Negotiation:
    case: dict[str, Any]
    threads: dict[str, list[dict[str, Any]]]
    table: RemoteTable
    lock: threading.RLock = field(default_factory=threading.RLock)
    closed_result: dict[str, Any] | None = None


class EmailTools:
    def __init__(self):
        self.client = ArenaClient()
        self.sessions: dict[str, Negotiation] = {}
        self.lock = threading.Lock()

    def get(self, session_id: str) -> Negotiation:
        with self.lock:
            negotiation = self.sessions.get(session_id)
        if negotiation is None:
            raise ValueError("Unknown session: start it with start_negotiation first")
        return negotiation


_tools: EmailTools | None = None
_tools_lock = threading.Lock()


def tools() -> EmailTools:
    global _tools
    with _tools_lock:
        if _tools is None:
            _tools = EmailTools()
    return _tools


def _supplier_thread(service: EmailTools, negotiation: Negotiation, session_id: str,
                     supplier_id: str) -> dict[str, Any]:
    """Refresh cached email events and extract any newly received attachments."""
    thread = service.client.thread(session_id, supplier_id)
    messages = thread.get("messages", [])
    for message in messages:
        load_attachments(negotiation.table, message)
    negotiation.threads[supplier_id] = messages
    return thread


def _refresh_live_threads(service: EmailTools, negotiation: Negotiation, session_id: str) -> None:
    for supplier_id in live_threads(negotiation.threads):
        _supplier_thread(service, negotiation, session_id, supplier_id)


def _policy_context(negotiation: Negotiation):
    agent = TaktikaAgent()
    research = agent.researcher.collect(negotiation.case)
    return agent, research


def _validate_term_sheets(negotiation: Negotiation, supplier_id: str,
                          term_sheets: list[dict[str, Any]], agent, research) -> None:
    case = negotiation.case
    standard = supplier_standard_terms(negotiation.threads[supplier_id])
    cap = agent.planner.batna(case, negotiation.threads, supplier_id, research)[0]
    planned = agent.planner.offer_packages(case, negotiation.threads, supplier_id, research)
    allowed = set(case.get("negotiable", []))
    options = case.get("term_options", {})
    for sheet in term_sheets:
        terms = sheet["terms"]
        if set(terms) - allowed:
            raise ValueError("Term sheets may only contain negotiable case fields")
        price = terms.get("unit_price")
        if (isinstance(price, bool) or not isinstance(price, (int, float))
                or not math.isfinite(float(price)) or float(price) <= 0):
            raise ValueError("Each term sheet needs a positive finite unit_price")
        for field, value in terms.items():
            if options.get(field) and value not in options[field]:
                raise ValueError(f"{field} must use one of the case's allowed options")
        if not must_haves_ok(case, terms, standard):
            raise ValueError("Term sheet violates a buyer must-have")
        cost = agent.planner.cost(case, terms, standard, supplier_id, research)
        if cost > cap + 0.01:
            raise ValueError("Term sheet exceeds the best available alternative")
        if complete_offer(case, terms) not in planned:
            raise ValueError("Term sheet is outside Taktika's current negotiation plan")


def _validate_acceptance(negotiation: Negotiation, supplier_id: str,
                         term_sheet_id: str, agent, research) -> None:
    current_id, terms = standing(negotiation.threads[supplier_id])
    if not term_sheet_id or term_sheet_id != current_id:
        raise ValueError("To accept, supply the current standing term_sheet_id")
    standard = supplier_standard_terms(negotiation.threads[supplier_id])
    if terms.get("unit_price") is None or not must_haves_ok(negotiation.case, terms, standard):
        raise ValueError("The current offer violates a buyer must-have")
    cap = agent.planner.batna(negotiation.case, negotiation.threads, supplier_id, research)[0]
    state = agent.planner._state(negotiation.case, supplier_id,
                                 negotiation.threads[supplier_id], research)
    threshold = agent.planner.acceptance_threshold(
        negotiation.case, negotiation.threads[supplier_id], state, cap
    )
    if state["cost"] > cap + 0.01 or state["cost"] > threshold + 0.01:
        raise ValueError("The current offer is outside Taktika's acceptance threshold")


@server.tool()
def list_arena_cases(set_name: Literal["practice", "sandbox", "final"] = "practice") -> list[dict[str, Any]]:
    """List available Arena cases without starting a negotiation."""
    return tools().client.cases(set_name)


@server.tool()
def start_negotiation(case_id: str) -> dict[str, Any]:
    """Open an Arena case and return the suppliers' opening emails and session ID."""
    service = tools()
    opened = service.client.open_session(case_id)
    session_id = opened["session_id"]
    table = RemoteTable(service.client, opened["case"])
    table.session_id = session_id
    threads = opened["threads"]
    for messages in threads.values():
        for message in messages:
            load_attachments(table, message)
    negotiation = Negotiation(opened["case"], threads, table)
    with service.lock:
        service.sessions[session_id] = negotiation
    return {
        "session_id": session_id,
        "case_id": opened["case"].get("case_id", case_id),
        "title": opened["case"].get("title"),
        "suppliers": list(threads),
        "opening_emails": threads,
    }


@server.tool()
def read_supplier_email(session_id: str, supplier_id: str) -> dict[str, Any]:
    """Read a supplier's latest Arena email thread, including extracted attachment text."""
    negotiation = tools().get(session_id)
    if supplier_id not in negotiation.threads:
        raise ValueError("Supplier is not part of this case")
    with negotiation.lock:
        thread = _supplier_thread(tools(), negotiation, session_id, supplier_id)
        messages = negotiation.threads[supplier_id]
        return {
            "supplier_id": supplier_id,
            "status": thread.get("status"),
            "standing_offer_id": thread.get("offer_id"),
            "messages": messages,
        }


@server.tool()
def draft_negotiation_email(session_id: str) -> dict[str, Any]:
    """Ask Taktika to choose the next supplier email or closing action; this does not send it."""
    negotiation = tools().get(session_id)
    with negotiation.lock:
        if negotiation.closed_result:
            return {"status": "closed", "result": negotiation.closed_result}
        _refresh_live_threads(tools(), negotiation, session_id)
        if not live_threads(negotiation.threads):
            return {"status": "no_open_threads"}
        decision = TaktikaAgent().decide(negotiation.case, negotiation.threads)
        return decision


@server.tool()
def send_negotiation_email(
    session_id: str,
    supplier_id: str,
    subject: str,
    body: str,
    term_sheets: list[dict[str, Any]] | None = None,
    refs: list[str] | None = None,
) -> dict[str, Any]:
    """Send an email and up to three term sheets to a supplier in the Arena session."""
    negotiation = tools().get(session_id)
    if supplier_id not in negotiation.threads:
        raise ValueError("Supplier is not part of this case")
    term_sheets = term_sheets or []
    refs = refs or []
    if len(term_sheets) > 3:
        raise ValueError("term_sheets must contain at most three term sheets")
    if any(not isinstance(sheet, dict) or not isinstance(sheet.get("terms"), dict)
           for sheet in term_sheets):
        raise ValueError("Each term sheet must be an object with a terms object")
    if len(refs) > 20:
        raise ValueError("refs must contain at most 20 reference IDs")
    if len(subject) > 300 or len(body) > 8000:
        raise ValueError("subject is limited to 300 characters and body to 8000 characters")
    message = {
        "subject": subject,
        "body": body,
        "term_sheets": term_sheets,
        "refs": refs,
    }
    with negotiation.lock:
        _refresh_live_threads(tools(), negotiation, session_id)
        if supplier_id not in live_threads(negotiation.threads):
            raise ValueError("That supplier thread is already closed")
        if term_sheets:
            agent, research = _policy_context(negotiation)
            _validate_term_sheets(negotiation, supplier_id, term_sheets, agent, research)
        reply = tools().client.send_message(session_id, supplier_id, message)
        if "result" in reply:
            negotiation.closed_result = reply["result"]
        else:
            negotiation.threads[supplier_id].extend([
                {**message, "from": "buyer"}, load_attachments(negotiation.table, reply),
            ])
        return {"buyer_email": message, "supplier_reply": reply}


@server.tool()
def close_negotiation(
    session_id: str,
    supplier_id: str,
    action: Literal["accept", "walk_away"],
    term_sheet_id: str = "",
) -> dict[str, Any]:
    """Accept the supplier's current offer or walk away, closing the Arena case."""
    negotiation = tools().get(session_id)
    if supplier_id not in negotiation.threads:
        raise ValueError("Supplier is not part of this case")
    with negotiation.lock:
        service = tools()
        _refresh_live_threads(service, negotiation, session_id)
        if supplier_id not in live_threads(negotiation.threads):
            raise ValueError("That supplier thread is already closed")
        if action == "accept":
            agent, research = _policy_context(negotiation)
            _validate_acceptance(negotiation, supplier_id, term_sheet_id, agent, research)
            payload = {"action": {"type": "accept", "term_sheet_id": term_sheet_id}}
        else:
            payload = {"action": {"type": "walk_away"}}
        result = service.client.send_message(session_id, supplier_id, payload)
        if "result" in result:
            negotiation.closed_result = result["result"]
            return negotiation.closed_result
        _supplier_thread(service, negotiation, session_id, supplier_id)
        if not live_threads(negotiation.threads):
            negotiation.closed_result = result
            return negotiation.closed_result
        return result


def main():
    load_dotenv()
    logging.basicConfig(level=os.getenv("LOG_LEVEL", "WARNING"))
    tools()
    server.run()


if __name__ == "__main__":
    main()
"""Standalone session orchestration for hosted practice, sandbox, and final cases."""

from __future__ import annotations

import functools
import logging
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from .client import ArenaError
from .cost_model import complete_offer, must_haves_ok, total_cost
from .document_reader import extract_text, supplier_standard_terms

log = logging.getLogger("taktika")
FINISHED = {"walked_away", "no_bid"}
RUNNING_SESSION = re.compile(r"one session per case in the final: (\S+)")


class RemoteTable:
    def __init__(self, client, case=None):
        self.client = client
        self.case = case
        self.session_id = None
        self.done = None

    def open(self, case_id):
        if self.session_id:
            return self.resume(self.session_id)
        try:
            response = self.client.open_session(case_id)
        except ArenaError as error:
            match = RUNNING_SESSION.search(str(error.detail)) if error.status == 409 else None
            if not match or self.case is None:
                raise
            return self.resume(match.group(1))
        self.session_id = response["session_id"]
        return response["case"], response["threads"]

    def resume(self, session_id):
        self.session_id = session_id
        state = self.client.session(session_id)
        if state.get("status") == "ended":
            self.done = self.result()
        threads = {
            supplier: self.client.thread(session_id, supplier).get("messages", [])
            for supplier in state.get("threads", {})
        }
        return self.case, threads

    def send(self, supplier, message):
        return self.client.send_message(self.session_id, supplier, message)

    def close(self, supplier, action):
        reply = self.send(supplier, action)
        return reply.get("result", reply)

    def get_attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {
            "deal": False, "end_reason": state.get("end_reason"), "session_id": self.session_id,
        }

    def after_conflict(self, supplier, error):
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        thread = self.client.thread(self.session_id, supplier)
        timeouts = thread.get("timeouts") or []
        if timeouts:
            latest_timeout = timeouts[-1]
            sheet_id = thread.get("offer_id")
            sheets = ([{"term_sheet_id": sheet_id, "terms": latest_timeout.get("terms", {})}]
                      if sheet_id else [])
            return {
                "from": "arena", "status": "walked_away" if thread.get("closed") else thread.get("status"),
                "term_sheets": sheets, "body": f"({error.detail})", "attachments": [],
            }
        messages = thread.get("messages", [])
        return messages[-1] if messages else {
            "from": "arena", "status": "walked_away", "term_sheets": [],
            "body": f"({error.detail})", "attachments": [],
        }


def latest(messages):
    return next(message for message in reversed(messages) if message.get("from") != "buyer")


def standing(messages):
    sheets = latest(messages).get("term_sheets") or []
    if not sheets:
        return None, {}
    first = sheets[0]
    return first.get("term_sheet_id"), first.get("terms", {})


def live_threads(threads):
    result = []
    for supplier, messages in threads.items():
        if messages and latest(messages).get("status") not in FINISHED:
            result.append(supplier)
    return result


def moves_left(case, messages):
    return case.get("round_limit", 10) - sum(message.get("from") == "buyer" for message in messages)


def load_attachments(table, message):
    for attachment in message.get("attachments") or []:
        identifier = attachment.get("attachment_id")
        if identifier and "text" not in attachment:
            attachment["text"] = extract_text(attachment.get("name", "attachment"),
                                              table.get_attachment(identifier))
    return message


def close_decision(case, threads):
    alternatives = []
    baseline = (case.get("buyer", {}).get("alternative") or {}).get("terms") or {}
    if baseline.get("unit_price") is not None and must_haves_ok(case, baseline):
        alternatives.append(total_cost(case, complete_offer(case, baseline)))
    fallback = case["buyer"].get("fallback_unit_price")
    if fallback is not None:
        fallback_offer = complete_offer(case, {"unit_price": fallback})
        if must_haves_ok(case, fallback_offer):
            alternatives.append(total_cost(case, fallback_offer))
    cap = min(alternatives, default=float("inf"))
    choices = []
    for supplier in live_threads(threads):
        offer_id, terms = standing(threads[supplier])
        standard = supplier_standard_terms(threads[supplier])
        if offer_id and terms.get("unit_price") is not None and must_haves_ok(case, terms, standard):
            amount = total_cost(case, terms, standard)
            if amount <= cap + 0.01:
                choices.append((amount, supplier, offer_id))
    if choices:
        _, supplier, offer_id = min(choices)
        return {"supplier_id": supplier,
                "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}
    return {"supplier_id": live_threads(threads)[0], "message": {"action": {"type": "walk_away"}}}


def play(table, case_id, agent, deadline=None):
    case, threads = table.open(case_id)
    if table.done:
        return table.done
    for events in threads.values():
        for message in events:
            load_attachments(table, message)
    longest_turn = 0.0
    while live_threads(threads):
        start = time.monotonic()
        cutoff = deadline() if callable(deadline) else deadline
        if cutoff and time.time() > cutoff - max(90.0, longest_turn + 15.0):
            decision = close_decision(case, threads)
        else:
            decision = agent.decide(case, threads)
        supplier, message = decision["supplier_id"], decision["message"]
        if message.get("action"):
            try:
                return table.close(supplier, message)
            except ArenaError as error:
                if error.status != 409:
                    raise
                reply = table.after_conflict(supplier, error)
                if "result" in reply:
                    return reply["result"]
                threads[supplier].append(load_attachments(table, reply))
                continue
        try:
            reply = table.send(supplier, message)
        except ArenaError as error:
            if error.status != 409:
                raise
            reply = table.after_conflict(supplier, error)
            if "result" not in reply:
                threads[supplier].append(load_attachments(table, reply))
                continue
        if "result" in reply:
            return reply["result"]
        threads[supplier].extend([
            {**message, "from": "buyer"}, load_attachments(table, reply),
        ])
        longest_turn = max(longest_turn, time.monotonic() - start)
        log.info("%s: %s", supplier, reply.get("status"))
    return table.result()


def hosted(cases):
    if any("hosted" in case for case in cases):
        return [case for case in cases if case.get("hosted")]
    return cases


def play_all(new_table, case_ids, new_agent, parallel=8):
    quota_spent = threading.Event()

    def run_one(case_id):
        if quota_spent.is_set():
            return case_id, ArenaError(429, "practice quota reached; case not started")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as error:
            if error.status == 429 and str(error.detail).startswith("practice limit"):
                quota_spent.set()
            log.exception("case %s could not finish", case_id)
            return case_id, error
        except Exception as error:
            log.exception("case %s failed", case_id)
            return case_id, error

    with ThreadPoolExecutor(max_workers=max(1, parallel)) as pool:
        return dict(pool.map(run_one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    futures, finished_waves, cutoffs = {}, set(), {}

    def start_case(case, cutoff):
        table = RemoteTable(client, case)
        return play(table, case["case_id"], new_agent(), functools.partial(cutoff.get, case["wave"]))

    with ThreadPoolExecutor(max_workers=max(1, min(parallel, 10))) as pool:
        while len(finished_waves) < waves or any(not future.done() for future in futures.values()):

